package app.cryptoresearch.mobile;
import java.net.URI;import java.util.Arrays;import okhttp3.*;import java.io.*;import org.json.JSONObject;
public final class PaperServerAPI {
 public static String canonical(String raw)throws Exception{URI u=new URI(raw.trim());if(!"https".equalsIgnoreCase(u.getScheme())||u.getHost()==null||u.getRawUserInfo()!=null||u.getRawQuery()!=null||u.getRawFragment()!=null||!(u.getPath().isEmpty()||u.getPath().equals("/")))throw new IllegalArgumentException("HTTPS 기본 서버 주소만 입력하세요");return u.toString().replaceAll("/$","");}
 public static boolean allowedPath(String path){
  if(Arrays.asList("api/v1/status","api/v1/report","api/v1/sessions/start","api/v1/sessions/pause","api/v1/diagnostics","api/v1/events?limit=50","api/v1/sessions?limit=100").contains(path))return true;
  if(path.matches("api/v1/sessions/[0-9a-f]{32}/report"))return true;
  if(path.matches("api/v1/events\\?limit=50&before=[0-9]{1,19}")){try{return Long.parseLong(path.substring(path.indexOf("before=")+7))>0;}catch(Exception e){return false;}}
  return false;
 }
 public static byte[] request(String base,String token,String path,JSONObject data)throws Exception {String root=canonical(base);if(token.length()<32||token.length()>512||token.contains("\n")||token.contains("\r")||(!allowedPath(path)||(data!=null&&!Arrays.asList("api/v1/sessions/start","api/v1/sessions/pause").contains(path))))throw new IllegalArgumentException("서버 토큰/요청 확인 필요");OkHttpClient client=new OkHttpClient.Builder().followRedirects(false).followSslRedirects(false).connectTimeout(12,java.util.concurrent.TimeUnit.SECONDS).readTimeout(15,java.util.concurrent.TimeUnit.SECONDS).callTimeout(20,java.util.concurrent.TimeUnit.SECONDS).build();Request.Builder b=new Request.Builder().url(root+"/"+path).header("Authorization","Bearer "+token).header("Accept","application/json");if(data!=null)b.post(RequestBody.create(data.toString(),MediaType.get("application/json")));try(Response r=client.newCall(b.build()).execute()){if(r.code()!=200){if(r.code()==401||r.code()==403)throw new IOException("토큰/읽기·제어 권한 확인 필요");if(r.code()==404)throw new IOException("기록이 없거나 서버1.4 이상이 필요합니다");if(r.code()==503)throw new IOException("서버 작업 중단 · 운영 상태 확인 후 서버 재시작 필요");if(r.code()==409)throw new IOException("이미 실행 중 · 정지 후 새 세션 시작");throw new IOException("서버 응답 오류 ("+r.code()+")");}if(r.body()==null)throw new IOException("서버 응답 없음");try(InputStream in=r.body().byteStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] buf=new byte[8192];int n;while((n=in.read(buf))!=-1){if(out.size()+n>8*1024*1024)throw new IOException("응답 크기 초과");out.write(buf,0,n);}return out.toByteArray();}}finally{client.dispatcher().cancelAll();client.dispatcher().executorService().shutdown();client.connectionPool().evictAll();}}
}
